using System.Windows; using System.Windows.Controls; using AshkanIndustrialOperations.Models; using AshkanIndustrialOperations.Services; namespace AshkanIndustrialOperations.Views; public partial class AssetsView:UserControl { readonly DemoDataService _d; public AssetsView(DemoDataService d){InitializeComponent();_d=d;DataContext=d;} void Add_Click(object s,RoutedEventArgs e){var n=AssetName.Text.Trim(); if(n.Length<2)return; _d.Machines.Add(new Machine{Name=n,Area=AreaName.Text.Trim(),Status="Commissioning",Oee=0,Temperature=24,Vibration=0,LastService="—"});_d.Log("Asset created",n);AssetName.Text="";} }